"""Recall node generated by aotn_node_helper."""

from typing import Any, ClassVar, Dict, List, Optional

from ... import saved_values as saved
from ...node_base import Node, NodeContext
from ...node_category import NodeCategory
from ...node_errors import NodeError
from ...system_access import finish


class RecallNode(Node):
    """Reads a value saved by an earlier run."""

    node_type: ClassVar[str] = 'recall_node'
    display_name: ClassVar[str] = 'Recall'
    default_alias: ClassVar[str] = 'Recall'
    description: ClassVar[str] = 'Reads a value saved by an earlier run'
    category: ClassVar[str] = NodeCategory.DATA
    primary_family: ClassVar[str] = 'Utility'
    tags: ClassVar[List[str]] = ['Saved values', 'across runs']
    icon_name: ClassVar[str] = 'archive-restore'
    color_hint: ClassVar[str] = 'grey'
    group: ClassVar[Optional[str]] = 'Saved values'
    selector_section: ClassVar[Optional[str]] = 'Saved values'
    input_ports: ClassVar[List[str]] = ['input']
    output_ports: ClassVar[List[str]] = ['default']
    input_port_metadata: ClassVar[Dict[str, Dict[str, Any]]] = {}
    output_port_metadata: ClassVar[Dict[str, Dict[str, Any]]] = {'default': {'name': 'Saved value', 'description': 'The value saved under this name', 'data_type': 'any', 'required': True, 'to': ['downstream', 'vault']}}
    default_config: ClassVar[Dict[str, Any]] = {'name': '', 'keep_for': 'This workflow', 'expect': 'any', 'if_missing': 'Use the starting value', 'starting_value': '', 'transient_output': True, 'dead_drop_passthrough': False, 'transient_outputs': [], 'vault_write': False, 'vault_write_key': '', 'vault_write_description': ''}
    config_schema: ClassVar[Dict[str, Dict[str, Any]]] = {'name': {'type': 'string', 'label': 'Saved as', 'required': True, 'placeholder': 'a name, like last_version', 'tab': 'Parameters'}, 'keep_for': {'type': 'select', 'label': 'Look in', 'options': [['This workflow · only this workflow sees it', 'This workflow'], ['All workflows · shared on this machine', 'All workflows']], 'tab': 'Parameters'}, 'expect': {'type': 'select', 'label': 'Type', 'options': [['any · whatever was saved', 'any'], ['string · text', 'string'], ['number', 'number'], ['bool · yes or no', 'bool'], ['var · a list or record', 'var'], ['file · a file reference', 'file']], 'tab': 'Parameters'}, 'if_missing': {'type': 'select', 'label': 'If nothing is saved yet', 'options': [['Use the starting value · below', 'Use the starting value'], ['Stop · the node fails', 'Stop with an error']], 'tab': 'Parameters'}, 'starting_value': {'type': 'string', 'label': 'Starting value', 'placeholder': 'blank = empty; read as the Type above', 'visible_when': {'if_missing': 'Use the starting value'}, 'tab': 'Parameters'}}
    ui_hints: ClassVar[Dict[str, Any]] = {'standard_output': True}
    error_definitions: ClassVar[List[Dict[str, Any]]] = [{'code': 'not_saved', 'description': 'Nothing is saved under this name yet.', 'retryable': False}, {'code': 'wrong_type', 'description': 'The saved value (or the starting value) is not the chosen Type.', 'retryable': False}, {'code': 'store_unreadable', 'description': 'The saved values file could not be read.', 'retryable': True}]

    @classmethod
    def describe_output_ports(cls, config: Optional[Dict[str, Any]]) -> Dict[str, Dict[str, Any]]:
        # The chosen Type is the output's type, so the next node knows it.
        expect = str((config or {}).get("expect") or "any")
        return {"default": {"data_type": expect if expect in saved.SAVED_TYPES else "any"}}

    async def execute(self, context: NodeContext) -> None:
        place = saved.place_for(self.config.get("keep_for"), context.workflow_name)
        name = str(self.config.get("name") or "").strip()
        expect = str(self.config.get("expect") or "any")
        try:
            if not name:
                raise saved.SavedValuesError("Saved as can't be blank", "node_error")
            record = saved.SavedValues().get(place, name)
            if record is None:
                if self.config.get("if_missing") == "Stop with an error":
                    raise saved.SavedValuesError(
                        f"Nothing is saved as '{name}' in {saved.place_label(place)} yet", "not_saved")
                value = _starting_value(str(self.config.get("starting_value") or ""), expect)
            elif expect != "any" and record["type"] != expect:
                raise saved.SavedValuesError(
                    f"'{name}' holds a {record['type']}, not a {expect}", "wrong_type")
            else:
                value = record["value"]
        except saved.SavedValuesError as exc:
            context.signal_error(NodeError(exc.code, str(exc), retryable=exc.code in saved.RETRYABLE))
            return
        finish(self, context, value, expect if expect != "any" else saved.type_of(value))


def _starting_value(text: str, expect: str) -> Any:
    """The Starting value read as the chosen Type; blank is that type's empty
    value (0, false, nothing)."""
    if expect in ("any", "string"):
        return text
    if not text.strip():
        return {"number": 0, "bool": False}.get(expect)
    return saved.parse_typed(text, expect)
